module TopModule (
    input  logic [3:0] x,
    output logic f
);
    // Trial 2: rows = {x[3], x[1]}, cols = {x[2], x[0]}
    // Let's unpack:
    logic r1, r0, c1, c0;
    assign r1 = x[3];
    assign r0 = x[1];
    assign c1 = x[2];
    assign c0 = x[0];

    // K-map table:
    //      c1 c0 -> 00  01  11  10
    // r1 r0
    // 00 | d | 0 | d | d |
    // 01 | 0 | d | 1 | 0 |
    // 11 | 1 | 1 | d | d |
    // 10 | 1 | 1 | 0 | d |

    logic [3:0] row_idx, col_idx;
    assign row_idx = {r1, r0};
    assign col_idx = {c1, c0};

    always_comb begin
        case ({row_idx, col_idx})
            8'b00_00: f = 1'b0; // d -> 0
            8'b00_01: f = 1'b0;
            8'b00_11: f = 1'b0; // d -> 0
            8'b00_10: f = 1'b0; // d -> 0

            8'b01_00: f = 1'b0;
            8'b01_01: f = 1'b1; // d -> 1
            8'b01_11: f = 1'b1;
            8'b01_10: f = 1'b0;

            8'b11_00: f = 1'b1;
            8'b11_01: f = 1'b1;
            8'b11_11: f = 1'b1; // d -> 1
            8'b11_10: f = 1'b1; // d -> 1

            8'b10_00: f = 1'b1;
            8'b10_01: f = 1'b1;
            8'b10_11: f = 1'b0;
            8'b10_10: f = 1'b0; // d -> 0
            default: f = 1'b0;
        endcase
    end
endmodule

